  runInline("
/* =========================================
   SHARED BACKGROUND SYSTEM
   Works with images AND videos
   ========================================= */

function setBackground(type, value = "") {

    // Save background for every page
    localStorage.setItem("bgType", type);
    localStorage.setItem("bgValue", value);
    localStorage.setItem(
        "activeBackground",
        value || type
    );

    applyBackground();
}


/* =========================================
   APPLY SAVED BACKGROUND
   ========================================= */

function applyBackground() {

    const type =
        localStorage.getItem("bgType") || "default";

    const value =
        localStorage.getItem("bgValue") || "";

    const bg =
        document.getElementById("bg");

    if (!bg) return;


    /*
     * Remove an old background video.
     */
    const oldVideo =
        bg.querySelector(".background-video");

    if (oldVideo) {
        oldVideo.pause();
        oldVideo.remove();
    }


    /*
     * Reset background.
     */
    bg.style.backgroundImage = "none";
    bg.style.backgroundColor = "transparent";


    /* =========================================
       DEFAULT
       ========================================= */

if (type === "default" || !value) {

    const defaultVideo =
        "/background-imgs/OMORILAB ORIGINAL ANIMATION MEME 3333.mp4";

    const video = document.createElement("video");

    video.className = "background-video";

    video.src = defaultVideo;

    video.autoplay = true;
    video.loop = true;
    video.muted = true;
    video.defaultMuted = true;
    video.playsInline = true;
    video.preload = "auto";

    video.setAttribute("aria-hidden", "true");

    Object.assign(video.style, {
        position: "absolute",
        inset: "0",
        width: "100%",
        height: "100%",
        objectFit: "cover",
        pointerEvents: "none",
        zIndex: "0",
        display: "block"
    });

    bg.appendChild(video);

    video.play().catch(() => {});

    return;
}


    /* =========================================
       COLOR
       ========================================= */

    if (type === "color") {

        bg.style.background = value;

        return;
    }


    /* =========================================
       IMAGE
       ========================================= */

    if (type === "image") {

        bg.style.background = "none";

        bg.style.backgroundImage =
            `url("${value.replace(/"/g, '\\"')}")`;

        bg.style.backgroundPosition =
            "center";

        bg.style.backgroundSize =
            "cover";

        bg.style.backgroundRepeat =
            "no-repeat";

        return;
    }


    /* =========================================
       VIDEO
       ========================================= */

    if (type === "video") {

        bg.style.background = "black";


        const video =
            document.createElement("video");

        video.className =
            "background-video";

        video.src = value;

        video.autoplay = true;
        video.loop = true;
        video.muted = true;
        video.defaultMuted = true;
        video.playsInline = true;
        video.preload = "auto";

        video.setAttribute(
            "aria-hidden",
            "true"
        );


        /*
         * Make video cover the entire screen.
         */
        video.style.position = "absolute";
        video.style.left = "0";
        video.style.top = "0";
        video.style.width = "100%";
        video.style.height = "100%";

        video.style.objectFit = "cover";

        video.style.pointerEvents = "none";

        video.style.zIndex = "0";

        video.style.display = "block";


        bg.appendChild(video);


        /*
         * Start playback.
         */
        video.addEventListener(
            "loadeddata",
            () => {

                video.play().catch(
                    error => {
                        console.warn(
                            "Video autoplay failed:",
                            error
                        );
                    }
                );

            },
            { once: true }
        );


        /*
         * Try immediately too.
         */
        video.play().catch(() => {});


        /*
         * If the video doesn't exist,
         * fall back to the normal background.
         */
        video.addEventListener(
            "error",
            () => {

                console.error(
                    "Could not load background video:",
                    value
                );

                video.remove();

                bg.style.background =
                    "linear-gradient(135deg, #000, rgb(183, 0, 255))";

            }
        );

        return;
    }


    /*
     * Unknown background type.
     */
    bg.style.background =
        "linear-gradient(135deg, #000, rgb(183, 0, 255))";
}


/* =========================================
   LOAD BACKGROUND WHEN HOME OPENS
   ========================================= */

window.addEventListener(
    "DOMContentLoaded",
    () => {

        applyBackground();

    }
);


/*
 * Also apply it on normal load.
 */
window.addEventListener(
    "load",
    () => {

        applyBackground();

    }
);
