      function createStars(color) {
        document.querySelectorAll(".star").forEach((s) => s.remove());
        for (let i = 0; i < 150; i++) {
          let star = document.createElement("div");
          star.className = "star";
          star.style.background = color;
          star.style.top = Math.random() * window.innerHeight + "px";
          star.style.left = Math.random() * window.innerWidth + "px";
          let size = Math.random() * 2 + 1;
          star.style.width = size + "px";
          star.style.height = size + "px";
          star.style.animation =
            "twinkle " + (Math.random() * 3 + 2) + "s infinite ease-in-out";
          document.body.appendChild(star);
        }
      }
    ");runInline("
      // Apply saved settings (theme + cloak)
      function applySettings() {
        let theme = localStorage.getItem("theme") || "dark";
        let accent = localStorage.getItem("accent") || "#9b59b6";
        let title = localStorage.getItem("cloakTitle");
        let icon = localStorage.getItem("cloakIcon");

        if (title) document.title = title;
        if (icon) {
          document
            .querySelectorAll('link[rel~="icon"]')
            .forEach((l) => l.remove());
          let link = document.createElement("link");
          link.rel = "icon";
          link.href = icon;
          document.head.appendChild(link);
        }

        if (theme === "light") {
          document.body.style.background = `linear-gradient(135deg,#ffffff,${accent})`;
          document.body.style.color = "black";
          createStars("black");
        } else {
          document.body.style.background = `linear-gradient(135deg,black,${accent})`;
          document.body.style.color = "white";
          createStars("white");
        }
      }

      window.addEventListener("load", applySettings);
    ");runInline("
      window.addEventListener("beforeunload", function (e) {
        e.preventDefault();
        e.returnValue = "";
