window.addEventListener("DOMContentLoaded", () => {
    const overlay = document.getElementById("overlay");

    if (!overlay) return;

    function closeSplash() {
        overlay.classList.add("hide");

        setTimeout(() => {
            overlay.remove();
        }, 600);
    }

    // Click anywhere on overlay = enter
    overlay.addEventListener("click", closeSplash);
});
");runInline("
    const inactiveOverlay =
        document.getElementById("inactiveOverlay");

    function updateInactiveOverlay() {
        if (document.hidden) {
            inactiveOverlay.classList.add("active");
        } else {
            inactiveOverlay.classList.remove("active");
        }
    }

    document.addEventListener(
        "visibilitychange",
        updateInactiveOverlay
    );

    window.addEventListener(
        "blur",
        () => {
            inactiveOverlay.classList.add("active");
        }
    );

    window.addEventListener(
        "focus",
        () => {
            if (!document.hidden) {
                inactiveOverlay.classList.remove("active");
            }
        }
    );

    updateInactiveOverlay();
");
})();
